from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
import requests
import urllib.parse
from django.conf import settings
from django.shortcuts import redirect
import boto3
import json


class DocumentPreviewRedirect(APIView):
    """Redirects user to document preview service based on provider URL."""

    ALLOWED_SCHEMES = ['http', 'https']

    def get(self, request):
        target_url = request.query_params.get('url', '')
        callback = request.query_params.get('callback', '')

        if not target_url:
            return Response({'error': 'url parameter required'}, status=400)

        parsed = urllib.parse.urlparse(target_url)

        # Validate scheme
        if parsed.scheme not in self.ALLOWED_SCHEMES:
            return Response({'error': 'Invalid scheme'}, status=400)

        # Build redirect URL through our preview renderer
        preview_url = f"{settings.PREVIEW_SERVICE_BASE}/render?source={urllib.parse.quote(target_url)}"

        if callback:
            preview_url += f"&callback={urllib.parse.quote(callback)}"

        return redirect(preview_url)


class InternalFetchView(APIView):
    """Internal endpoint used by preview service to fetch document content.
    Intended to be called only from internal preview microservice."""

    def post(self, request):
        fetch_url = request.data.get('source_url', '')

        if not fetch_url:
            return Response({'error': 'source_url required'}, status=400)

        # Fetch the document content
        try:
            resp = requests.get(
                fetch_url,
                timeout=10,
                headers={'User-Agent': 'DocPreview-Internal/1.0'}
            )
            content_type = resp.headers.get('Content-Type', 'application/octet-stream')

            return Response({
                'content': resp.text[:50000],
                'content_type': content_type,
                'status_code': resp.status_code
            })
        except requests.exceptions.RequestException as e:
            return Response({'error': str(e)}, status=502)


class MetadataEnrichView(APIView):
    """Enriches document metadata using AWS services."""

    def post(self, request):
        document_content = request.data.get('content', '')
        action = request.data.get('action', 'detect_text')

        session = boto3.Session()

        if action == 'detect_text':
            client = session.client('textract')
            # Process with Textract
            result = {'service': 'textract', 'status': 'processed'}
        elif action == 'get_secret':
            client = session.client('secretsmanager')
            secret_id = request.data.get('secret_id', '')
            try:
                response = client.get_secret_value(SecretId=secret_id)
                result = {'secret': response.get('SecretString', '')}
            except Exception as e:
                result = {'error': str(e)}
        elif action == 'assume_role':
            client = session.client('sts')
            role_arn = request.data.get('role_arn', '')
            try:
                response = client.assume_role(
                    RoleArn=role_arn,
                    RoleSessionName='doc-enrichment'
                )
                result = {'credentials': str(response['Credentials'])}
            except Exception as e:
                result = {'error': str(e)}
        elif action == 'invoke_lambda':
            client = session.client('lambda')
            func_name = request.data.get('function_name', '')
            try:
                response = client.invoke(
                    FunctionName=func_name,
                    Payload=json.dumps({'content': document_content[:1000]})
                )
                result = {'response': response['Payload'].read().decode()}
            except Exception as e:
                result = {'error': str(e)}
        else:
            result = {'error': 'Unknown action'}

        return Response(result)


